//! Acceptance tests for the `deno.lock` provider (#1924, spec 091).
//!
//! Lock keys are normalized by the Deno CLI (`^1.0.0` -> `1`, unversioned -> `*`, two
//! requests merged into one key), so resolution must match by package name, never by the
//! exact manifest specifier.

#![allow(clippy::unwrap_used)]

use std::assert_matches;
use std::path::Path;
use std::sync::Arc;

use deps_core::lockfile::{LockFileProvider, ResolvedPackages};
use deps_core::{DepsError, EcosystemBase, HttpCache};
use deps_deno::{DenoEcosystem, DenoLockParser};
use url::Url;

/// Generated by deno 2.9.8 from a `deno.json` whose imports are `jsr:@std/path@^1.0.0`,
/// `jsr:@std/assert`, `npm:chalk@^5`, `npm:react-dom@^18.2.0`, `jsr:@std/path@^1/posix`.
const V5: &str = r#"{
  "version": "5",
  "specifiers": {
    "jsr:@std/assert@*": "1.0.19",
    "jsr:@std/internal@^1.0.12": "1.0.14",
    "jsr:@std/internal@^1.0.14": "1.0.14",
    "jsr:@std/path@1": "1.1.6",
    "npm:chalk@5": "5.6.2",
    "npm:react-dom@^18.2.0": "18.3.1_react@18.3.1"
  },
  "jsr": {
    "@std/path@1.1.6": { "integrity": "c68485c2" }
  },
  "npm": {
    "chalk@5.6.2": { "integrity": "sha512-7NzBL0" }
  },
  "workspace": {
    "dependencies": ["jsr:@std/assert@*", "jsr:@std/path@1", "npm:chalk@5"]
  }
}"#;

const V4: &str = r#"{
  "version": "4",
  "specifiers": {
    "jsr:@std/path@^1.0.0": "1.0.8",
    "npm:chalk@^5": "5.3.0"
  },
  "jsr": {},
  "npm": {},
  "remote": { "https://deno.land/x/foo/mod.ts": "abc123" }
}"#;

const V3: &str = r#"{
  "version": "3",
  "packages": {
    "specifiers": {
      "jsr:@std/path@^1.0.0": "jsr:@std/path@1.0.8",
      "npm:chalk@^5": "npm:chalk@5.3.0"
    },
    "jsr": {},
    "npm": {}
  },
  "remote": {},
  "workspace": {}
}"#;

async fn parse(dir: &Path, content: &str) -> deps_core::Result<ResolvedPackages> {
    let path = dir.join("deno.lock");
    tokio::fs::write(&path, content).await.unwrap();
    DenoLockParser.parse_lockfile(&path).await
}

#[tokio::test]
async fn parse_lockfile_v5_matches_by_name_across_normalized_keys() {
    let dir = tempfile::tempdir().unwrap();
    let packages = parse(dir.path(), V5).await.unwrap();
    assert!(!packages.is_empty());
    assert_eq!(packages.version("jsr:@std/path"), Some("1.1.6"));
    assert_eq!(packages.version("jsr:@std/assert"), Some("1.0.19"));
    assert_eq!(packages.version("jsr:@std/internal"), Some("1.0.14"));
    assert_eq!(packages.version("npm:chalk"), Some("5.6.2"));
}

#[tokio::test]
async fn parse_lockfile_v5_strips_npm_peer_suffix() {
    let dir = tempfile::tempdir().unwrap();
    let packages = parse(dir.path(), V5).await.unwrap();
    assert_eq!(packages.version("npm:react-dom"), Some("18.3.1"));
}

#[tokio::test]
async fn parse_lockfile_v4_reads_top_level_specifiers() {
    let dir = tempfile::tempdir().unwrap();
    let packages = parse(dir.path(), V4).await.unwrap();
    assert_eq!(packages.len(), 2);
    assert_eq!(packages.version("jsr:@std/path"), Some("1.0.8"));
    assert_eq!(packages.version("npm:chalk"), Some("5.3.0"));
}

#[tokio::test]
async fn parse_lockfile_v3_reads_nested_prefixed_specifiers() {
    let dir = tempfile::tempdir().unwrap();
    let packages = parse(dir.path(), V3).await.unwrap();
    assert_eq!(packages.len(), 2);
    assert_eq!(packages.version("jsr:@std/path"), Some("1.0.8"));
    assert_eq!(packages.version("npm:chalk"), Some("5.3.0"));
}

#[tokio::test]
async fn parse_lockfile_remote_only_yields_empty_set() {
    let dir = tempfile::tempdir().unwrap();
    let content = r#"{"version":"4","remote":{"https://deno.land/x/a.ts":"deadbeef"}}"#;
    assert!(parse(dir.path(), content).await.unwrap().is_empty());
}

#[tokio::test]
async fn parse_lockfile_skips_non_string_values() {
    let dir = tempfile::tempdir().unwrap();
    let content = r#"{"version":"5","specifiers":{"jsr:@std/path@1":42,"npm:chalk@5":"5.6.2"}}"#;
    let packages = parse(dir.path(), content).await.unwrap();
    assert!(packages.get("jsr:@std/path").is_none());
    assert_eq!(packages.version("npm:chalk"), Some("5.6.2"));
}

#[tokio::test]
async fn parse_lockfile_missing_version_is_parse_error() {
    let dir = tempfile::tempdir().unwrap();
    let err = parse(dir.path(), r#"{"specifiers":{}}"#).await.unwrap_err();
    assert_matches!(err, DepsError::ParseError { .. }, "got {err:?}");
}

#[tokio::test]
async fn parse_lockfile_non_string_version_is_parse_error() {
    let dir = tempfile::tempdir().unwrap();
    let err = parse(dir.path(), r#"{"version":5,"specifiers":{}}"#)
        .await
        .unwrap_err();
    assert_matches!(err, DepsError::ParseError { .. }, "got {err:?}");
}

#[tokio::test]
async fn parse_lockfile_unsupported_version_is_parse_error_naming_it() {
    let dir = tempfile::tempdir().unwrap();
    let err = parse(dir.path(), r#"{"version":"99","specifiers":{}}"#)
        .await
        .unwrap_err();
    assert_matches!(err, DepsError::ParseError { .. }, "got {err:?}");
    assert!(err.to_string().contains("99"), "{err}");
}

#[tokio::test]
async fn parse_lockfile_invalid_json_is_parse_error() {
    let dir = tempfile::tempdir().unwrap();
    let err = parse(dir.path(), "{oops").await.unwrap_err();
    assert_matches!(err, DepsError::ParseError { .. }, "got {err:?}");
}

#[tokio::test]
async fn parse_lockfile_too_deep_is_parse_error() {
    let dir = tempfile::tempdir().unwrap();
    let deep = format!("{}{}", "[".repeat(10_000), "]".repeat(10_000));
    let err = parse(dir.path(), &deep).await.unwrap_err();
    assert_matches!(err, DepsError::ParseError { .. }, "got {err:?}");
}

#[test]
fn locate_lockfile_finds_deno_lock_for_deno_json_and_deno_jsonc() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("deno.lock"), V5).unwrap();
    for manifest in ["deno.json", "deno.jsonc"] {
        let uri = Url::from_file_path(dir.path().join(manifest)).unwrap();
        assert_eq!(
            DenoLockParser.locate_lockfile(&uri),
            Some(dir.path().join("deno.lock")),
            "{manifest}"
        );
    }
}

#[test]
fn locate_lockfile_finds_ancestor_deno_lock_for_nested_manifest() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("deno.lock"), V5).unwrap();
    let nested = dir.path().join("packages").join("app");
    std::fs::create_dir_all(&nested).unwrap();
    let uri = Url::from_file_path(nested.join("deno.json")).unwrap();
    assert_eq!(
        DenoLockParser.locate_lockfile(&uri),
        Some(dir.path().join("deno.lock"))
    );
}

#[test]
fn locate_lockfile_absent_returns_none() {
    let dir = tempfile::tempdir().unwrap();
    let uri = Url::from_file_path(dir.path().join("deno.json")).unwrap();
    assert_eq!(DenoLockParser.locate_lockfile(&uri), None);
}

#[test]
fn lockfile_filenames_is_deno_lock() {
    let eco = DenoEcosystem::new(Arc::new(HttpCache::new()));
    assert_eq!(eco.lockfile_filenames(), &["deno.lock"]);
    assert!(eco.lockfile_provider().is_some());
}
